const SEXES=[['Female','Female / महिला'],['Male','Male / पुरुष'],['Other','Other / अन्य'],['Unknown','Unknown / अज्ञात']];
const PROGRAMME_LIST=[['General care','General care / सामान्य देखभाल'],['Maternal care','Maternal care / मातृ देखभाल'],['Chronic care','Chronic care / दीर्घकालिक देखभाल'],['TB screening','TB screening / टीबी जाँच'],['Child health','Child health / बाल स्वास्थ्य']];
