const blankForm=()=>({name:'',age:'',sex:'',village:'',programme:'General care',teamId:'',withVisit:false,facts:{date:new Date().toISOString().slice(0,16),systolic:'',diastolic:'',weight:'',temperature:'',weeks:'',coughDays:'',notes:'',source:'measured'},withReferral:false,referral:{facility:'',reason:''}});
