const MEASURE_FIELDS={bloodPressure:['systolic','diastolic'],weight:['weight'],temperature:['temperature'],weeks:['weeks'],coughDays:['coughDays']};
const MEASURE_NAMES={bloodPressure:'Blood pressure / रक्तचाप',weight:'Weight / वज़न',temperature:'Temperature / तापमान',weeks:'Gestational age / गर्भावस्था की अवधि',coughDays:'Cough duration / खाँसी की अवधि'};
