 for(const [k,a] of Object.entries(ALT_UNITS)){const e=facts.entered?.[k],r=VALUE_RANGES.fields[k],g=node('div',null,{className:'grid'});
  g.append(choice(`${r.label} · unit / इकाई`,e?a.unit:'',[['',r.unit],[a.unit,a.label]],x=>{const n={...(facts.entered??{})};if(x)n[k]={value:e?.value??'',unit:x};else delete n[k];if(Object.keys(n).length)facts.entered=n;else delete facts.entered;},disabled),field(`${r.label} · value in ${a.label}`,e?.value??'',x=>{if(facts.entered?.[k])facts.entered[k].value=x;},'text',disabled||!e));box.append(g);
  if(e)box.append(node('p',`The ${r.unit} value above is replaced by the converted value when syncing.${convertEntered(k,e)?` ${e.value} → ${convertEntered(k,e)} ${r.unit}.`:''} / सिंक पर बदला जाएगा।`,{className:'muted'}));}
